local function tween(obj, props, time, style, dir)
    local info = TweenInfo.new(time or 0.25, style or Enum.EasingStyle.Quart, dir or Enum.EasingDirection.Out)
    local t = TweenService:Create(obj, info, props) t:Play() return t
end
local function notify(title, text) pcall(function() StarterGui:SetCore("SendNotification", {Title=title, Text=text, Duration=2.5}) end) end
local function doTeleport(x,y,z,label)
    local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hrp = char:WaitForChild("HumanoidRootPart",5)
    if not hrp then return end
    local target = CFrame.new(x,y+3,z)
    local dist=(hrp.Position-Vector3.new(x,y,z)).Magnitude
    if dist>3500 then hrp.CFrame=target pcall(function() hrp.AssemblyLinearVelocity=Vector3.zero end)
    else local tw=TweenService:Create(hrp,TweenInfo.new(0.35,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{CFrame=target}) tw:Play() task.delay(0.4,function() if (hrp.Position-Vector3.new(x,y,z)).Magnitude>10 then hrp.CFrame=target end end) end
    if _G.__teleportToast then _G.__teleportToast(label,string.format("%d, %d, %d",x,y,z)) end
    notify("Телепорт → "..label,string.format("X:%d Y:%d Z:%d",x,y,z))
end
-- player helpers (лёгкие, без аватаров)
local playerSearchText=""
local playerListFrame, playerSearchBox, playerCountLabel, playerRefreshBtn
local function getHRP(char) return char and char:FindFirstChild("HumanoidRootPart") end
local function teleportToPlayer(p)
    if not p or not p.Character then notify("Игрок","Нет персонажа") return end
    local th=getHRP(p.Character) if not th then return end
    local char=LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
    local hrp=char:WaitForChild("HumanoidRootPart",5) if not hrp then return end
    local off=th.CFrame.LookVector*3+Vector3.new(0,1.5,0)
    hrp.CFrame=CFrame.new(th.Position+off)
    pcall(function() hrp.AssemblyLinearVelocity=Vector3.zero end) hrp.Velocity=Vector3.zero
    notify("→ "..p.Name,string.format("К %s (@%s)",p.DisplayName,p.Name))
    if _G.__teleportToast then _G.__teleportToast("→ "..p.Name,string.format("%.0f, %.0f, %.0f",th.Position.X,th.Position.Y,th.Position.Z)) end
end
local function refreshPlayerList()
    if not playerListFrame then return end
    for _,ch in ipairs(playerListFrame:GetChildren()) do if ch:IsA("Frame") then ch:Destroy() end end
    local q=playerSearchText:lower():gsub("%s+","")
    local players=Players:GetPlayers()
    local filtered={}
    for _,p in ipairs(players) do if p~=LocalPlayer then if q=="" or p.Name:lower():find(q,1,true) or p.DisplayName:lower():find(q,1,true) then table.insert(filtered,p) end end end
    table.sort(filtered,function(a,b) return a.Name:lower()<b.Name:lower() end)
    if playerCountLabel then playerCountLabel.Text=#filtered.." игроков"..(q~="" and " • фильтр" or "") end
    if #filtered==0 then local e=Instance.new("TextLabel") e.BackgroundTransparency=1 e.Size=UDim2.new(1,-8,0,28) e.Font=Enum.Font.Gotham e.Text=(q~="" and "Никого" or "Нет игроков") e.TextColor3=Color3.fromRGB(110,110,125) e.TextSize=11 e.Parent=playerListFrame return end
    for _,p in ipairs(filtered) do
        local row=Instance.new("Frame") row.Size=UDim2.new(1,-6,0,34) row.BackgroundColor3=Color3.fromRGB(26,26,32) row.Parent=playerListFrame local rc=Instance.new("UICorner") rc.CornerRadius=UDim.new(0,8) rc.Parent=row local rs=Instance.new("UIStroke") rs.Color=Color3.fromRGB(45,45,55) rs.Transparency=0.6 rs.Parent=row
        local av=Instance.new("Frame") av.Size=UDim2.fromOffset(24,24) av.Position=UDim2.fromOffset(6,5) av.BackgroundColor3=Color3.fromRGB(124,92,255) av.BackgroundTransparency=0.85 av.Parent=row local ac=Instance.new("UICorner") ac.CornerRadius=UDim.new(1,0) ac.Parent=av local al=Instance.new("TextLabel") al.BackgroundTransparency=1 al.Size=UDim2.fromScale(1,1) al.Font=Enum.Font.GothamBold al.Text=p.DisplayName:sub(1,1):upper() al.TextColor3=Color3.fromRGB(124,92,255) al.TextSize=12 al.Parent=av
        local n=Instance.new("TextLabel") n.BackgroundTransparency=1 n.Position=UDim2.fromOffset(36,4) n.Size=UDim2.new(1,-78,0,12) n.Font=Enum.Font.GothamBold n.Text=p.DisplayName n.TextColor3=Color3.fromRGB(255,255,255) n.TextSize=11 n.TextXAlignment=Enum.TextXAlignment.Left n.TextTruncate=Enum.TextTruncate.AtEnd n.Parent=row
        local u=Instance.new("TextLabel") u.BackgroundTransparency=1 u.Position=UDim2.fromOffset(36,18) u.Size=UDim2.new(1,-78,0,10) u.Font=Enum.Font.Gotham u.Text="@"..p.Name u.TextColor3=Color3.fromRGB(130,130,145) u.TextSize=10 n.TextXAlignment=Enum.TextXAlignment.Left u.Parent=row
        local b=Instance.new("TextButton") b.Size=UDim2.fromOffset(36,22) b.Position=UDim2.new(1,-42,0.5,-11) b.BackgroundColor3=Color3.fromRGB(124,92,255) b.Text="TP" b.Font=Enum.Font.GothamBold b.TextSize=10 b.TextColor3=Color3.fromRGB(255,255,255) b.Parent=row local bc=Instance.new("UICorner") bc.CornerRadius=UDim.new(0,7) bc.Parent=b
        b.MouseButton1Click:Connect(function() teleportToPlayer(p) end)
    end
end
