for _,tp in ipairs(TELEPORTS) do local card=Instance.new("TextButton") card.Name=tp.name card.BackgroundColor3=Color3.fromRGB(26,26,32) card.Text="" card.AutoButtonColor=false card.Parent=scroll local co=Instance.new("UICorner") co.CornerRadius=UDim.new(0,12) co.Parent=card local st=Instance.new("UIStroke") st.Color=Color3.fromRGB(45,45,55) st.Transparency=0.5 st.Parent=card local ac=Instance.new("Frame") ac.Size=UDim2.new(0,3,1,-16) ac.Position=UDim2.fromOffset(8,8) ac.BackgroundColor3=tp.color ac.Parent=card local acc=Instance.new("UICorner") acc.CornerRadius=UDim.new(1,0) acc.Parent=ac local ic3=Instance.new("Frame") ic3.Size=UDim2.fromOffset(34,34) ic3.Position=UDim2.fromOffset(18,11) ic3.BackgroundColor3=tp.color ic3.BackgroundTransparency=0.88 ic3.Parent=card local icc3=Instance.new("UICorner") icc3.CornerRadius=UDim.new(1,0) icc3.Parent=ic3 local iss=Instance.new("UIStroke") iss.Color=tp.color iss.Transparency=0.6 iss.Parent=ic3 local it=Instance.new("TextLabel") it.BackgroundTransparency=1 it.Size=UDim2.fromScale(1,1) it.Font=Enum.Font.GothamBold it.Text=tp.icon it.TextColor3=tp.color it.TextSize=14 it.Parent=ic3 local nm=Instance.new("TextLabel") nm.BackgroundTransparency=1 nm.Position=UDim2.fromOffset(60,10) nm.Size=UDim2.new(1,-96,0,14) nm.Font=Enum.Font.GothamBold nm.Text=tp.name nm.TextColor3=Color3.fromRGB(255,255,255) nm.TextSize=12 nm.Parent=card local co2=Instance.new("TextLabel") co2.BackgroundTransparency=1 co2.Position=UDim2.fromOffset(60,26) co2.Size=UDim2.new(1,-96,0,12) co2.Font=Enum.Font.Gotham co2.Text=string.format("%d ,  %d ,  %d",tp.x,tp.y,tp.z) co2.TextColor3=Color3.fromRGB(140,140,155) co2.TextSize=11 co2.Parent=card local ar=Instance.new("Frame") ar.Size=UDim2.fromOffset(28,28) ar.Position=UDim2.new(1,-38,0.5,-14) ar.BackgroundColor3=Color3.fromRGB(35,35,42) ar.Parent=card local arc=Instance.new("UICorner") arc.CornerRadius=UDim.new(0,8) arc.Parent=ar local arl=Instance.new("TextLabel") arl.BackgroundTransparency=1 arl.Size=UDim2.fromScale(1,1) arl.Font=Enum.Font.GothamBold arl.Text="→" arl.TextColor3=Color3.fromRGB(170,170,180) arl.TextSize=13 arl.Parent=ar card.MouseEnter:Connect(function() tween(card,{BackgroundColor3=Color3.fromRGB(32,32,40)},0.15) tween(st,{Color=tp.color,Transparency=0.25},0.15) tween(ar,{BackgroundColor3=tp.color},0.15) tween(arl,{TextColor3=Color3.fromRGB(255,255,255)},0.15) end) card.MouseLeave:Connect(function() tween(card,{BackgroundColor3=Color3.fromRGB(26,26,32)},0.15) tween(st,{Color=Color3.fromRGB(45,45,55),Transparency=0.5},0.15) tween(ar,{BackgroundColor3=Color3.fromRGB(35,35,42)},0.15) tween(arl,{TextColor3=Color3.fromRGB(170,170,180)},0.15) end) card.MouseButton1Click:Connect(function() doTeleport(tp.x,tp.y,tp.z,tp.name) end) end
task.spawn(function() task.wait(0.15) local function upd() local rows=math.ceil(#TELEPORTS/2) scroll.CanvasSize=UDim2.new(0,0,0,rows*64+4) if psListHolder and playerListFrame then local need=playerListFrame.AbsoluteContentSize.Y+4 if need<1 then need=34 end psListHolder.CanvasSize=UDim2.new(0,0,0,need) end end upd() grid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() task.wait() upd() end) if playerListFrame then playerListFrame:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() task.wait() upd() end) end scroll:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(upd) if psListHolder then psListHolder:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(upd) end for i=1,20 do task.wait(0.1) upd() end end)
if playerSearchBox then playerSearchBox:GetPropertyChangedSignal("Text"):Connect(function() playerSearchText=playerSearchBox.Text refreshPlayerList() end) end
if playerRefreshBtn then playerRefreshBtn.MouseButton1Click:Connect(function() refreshPlayerList() end) end
task.spawn(function() task.wait(0.6) pcall(refreshPlayerList) Players.PlayerAdded:Connect(function() task.wait(0.4) pcall(refreshPlayerList) end) Players.PlayerRemoving:Connect(function() task.wait(0.1) pcall(refreshPlayerList) end) end)
do local dragging,dragStart,startPos topBar.InputBegan:Connect(function(inp) if inp.UserInputType==Enum.UserInputType.MouseButton1 then dragging=true dragStart=inp.Position startPos=main.Position inp.Changed:Connect(function() if inp.UserInputState==Enum.UserInputState.End then dragging=false end end) end end) UserInputService.InputChanged:Connect(function(inp) if dragging and inp.UserInputType==Enum.UserInputType.MouseMovement then local d=inp.Position-dragStart main.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+d.X,startPos.Y.Scale,startPos.Y.Offset+d.Y) end end) end
local isOpen=true local originalSize=main.Size local function setOpen(o,i) isOpen=o if o then gui.Enabled=true blur.Visible=true main.Visible=true if i then main.Size=originalSize main.BackgroundTransparency=0 else main.Size=UDim2.fromOffset(originalSize.X.Offset*0.92,originalSize.Y.Offset*0.92) main.BackgroundTransparency=1 tween(main,{Size=originalSize,BackgroundTransparency=0},0.28,Enum.EasingStyle.Back) tween(blur,{BackgroundTransparency=0.25},0.28) end else if i then main.Visible=false blur.Visible=false gui.Enabled=false else local t1=tween(main,{Size=UDim2.fromOffset(originalSize.X.Offset*0.92,originalSize.Y.Offset*0.92),BackgroundTransparency=1},0.22) tween(blur,{BackgroundTransparency=1},0.22) t1.Completed:Wait() main.Visible=false blur.Visible=false end end end
closeBtn.MouseButton1Click:Connect(function() setOpen(false) end) minimizeBtn.MouseButton1Click:Connect(function() end)
UserInputService.InputBegan:Connect(function(inp,gp) if gp then return end if inp.KeyCode==Enum.KeyCode.RightBracket then setOpen(not isOpen) end end)
setOpen(true,true)
